return [{ payload: { kind: 'log', text: out, state: state } }, { topic: 'check' }];

// Test bench Teensy: firmware update (double click), balancing, version info.
// Outputs: flash exec, ui, Teensy serial.
const now = Date.now();
const t = msg.topic;
const ui = (text) => ({ payload: { kind: 'state', text: text } });
if (t === 'check' || t === 'info') {
    const info = { running: flow.get('teensyFw') || null, board: flow.get('teensyHw') || null,
                   latestFw: global.get('teslabmsLatestFw') || null };
    return [null, { payload: { kind: 'info', info: info } }, null];
}
if (t === 'proto') {
    // CAN protocol to the inverter: 0 Victron, 1 LG RESU LV (SolarEdge). Double click (10 s).
    const p = Number(msg.payload) === 1 ? 1 : 0;
    const armed = context.get('armedProto') || {};
    if (armed.p === p && (now - armed.at) < 10000) {
        context.set('armedProto', {});
        return [null, ui('CAN protocol sent: ' + (p ? 'LG RESU LV (SolarEdge)' : 'Victron') + ' (needs firmware v26.29)'), { payload: 'P' + p + '\n' }];
    }
    context.set('armedProto', { p: p, at: now });
    return [null, ui('Click again within 10 s to switch the CAN protocol to ' + (p ? 'LG RESU LV (SolarEdge)' : 'Victron')), null];
}
if (t === 'bal') {
    const p = msg.payload || {};
    const a = Math.round(Number(p.start)), b = Math.round(Number(p.stop));
    if (!(b >= 2 && b <= 50 && a > b && a <= 100)) return [null, ui('Balancing: invalid values'), null];
    return [null, ui(`Balancing sent: start > ${a} mV, down to ${b} mV`), { payload: `B${a},${b}\n` }];
}
if (t === 'fw') {
    if (flow.get('teslabmsBusy')) return [null, ui('An update is already running - please wait'), null];
    const gb = global.get('teslabmsFlashBusy') || 0;
    if (now - gb < 300000) return [null, ui('A firmware update of the other Teensy is running - please wait'), null];
    const armed = context.get('armed') || {};
    if (armed.t === t && (now - armed.at) < 10000) {
        context.set('armed', {});
        const hw = flow.get('teensyHw') || 'T32';
        const port = flow.get('teensyPort');
        if (!port) return [null, ui('Test Teensy port unknown - wait until data arrives'), null];
        flow.set('teslabmsBusy', true);
        global.set('teslabmsFlashBusy', now);
        node.status({ fill: 'yellow', shape: 'dot', text: 'flashing test Teensy...' });
        return [{ payload: '--board ' + hw + ' --port ' + port }, ui('Test Teensy firmware update running...'), null];
    }
    context.set('armed', { t: t, at: now });
    return [null, ui('Click "Update Teensy firmware" again within 10 seconds to confirm.'), null];
}
return null;

// Port of the test bench Teensy, decided by "Assign Teensy ports" in the tab "Tesla BMS".
const port = msg.payload;
if (!port) {
    node.status({ fill: 'grey', shape: 'ring', text: 'no test Teensy connected' });
    return null;
}
const now = Date.now();
const cur = flow.get('teensyPort');
const silent = (now - (flow.get('teensyLastData') || 0)) > 60000;
const lr = context.get('lastReconnect') || 0;
node.status({ fill: 'green', shape: 'dot', text: port.replace('/dev/serial/by-id/', '') });
if (port !== cur || (silent && now - lr > 60000)) {
    flow.set('teensyPort', port);
    context.set('lastReconnect', now);
    return { payload: port + ' /data/home/nodered/.node-red/teslabms-tty-test' };   // -> ln -sfn <Teensy> <test link> -> reopen
}
return null;

// The symlink /data/home/nodered/.node-red/teslabms-tty-main now points at the right Teensy: reopen this tab's own serial connection.
// (Each tab has its own fixed port name, so two tabs never share a connection.)
const ok = msg.payload && msg.payload.code === 0;
node.status({ fill: ok ? 'green' : 'red', shape: 'dot', text: ok ? 'reopened' : 'ln failed: ' + JSON.stringify(msg.payload) });
return { payload: { serialport: '/data/home/nodered/.node-red/teslabms-tty-main', serialbaud: 115200 } };

